SELECT percent_rank() OVER (ORDER BY vital_instability_score) AS percentile_rank, AVG(los) AS average_length_of_stay, SUM(CASE WHEN s.dod IS NOT NULL THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(s.subject_id), 0) AS mortality_rate FROM first_24h_vital_instability WHERE value = 70 AND subject_id IN (SELECT subject_id FROM acs_patients) GROUP BY subject_id, anchor_age ORDER BY percentile_rank NULLS LAST LIMIT 10;